import base64, zlib
from pathlib import Path

# Approved user-supplied branding images, compressed and embedded so the Windows build is self-contained.
LOGO_B64 = ''''''

SPLASH_B64 = ''''''

def materialize_assets(root):
    root = Path(root)
    root.mkdir(parents=True, exist_ok=True)
    logo = zlib.decompress(base64.b64decode(LOGO_B64))
    splash = zlib.decompress(base64.b64decode(SPLASH_B64))
    logo_path = root / 'trader_planner_logo.jpg'
    splash_path = root / 'trader_planner_splash.jpg'
    logo_path.write_bytes(logo)
    splash_path.write_bytes(splash)
    return logo_path, splash_path
